package com.movieticket.booking; import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="bookings") public class Booking {@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="show_id",nullable=false)private Long showId;@Column(name="seat_number",nullable=false)private String seatNumber;@Column(nullable=false)private String email;@Column(nullable=false)private String status="CONFIRMED";@Column(nullable=false)private Instant bookedAt=Instant.now();protected Booking(){}public Booking(Long s,String seat,String e){showId=s;seatNumber=seat;email=e;}public Long getId(){return id;}public Long getShowId(){return showId;}public String getSeatNumber(){return seatNumber;}public String getEmail(){return email;}public String getStatus(){return status;}public Instant getBookedAt(){return bookedAt;}public void setStatus(String s){status=s;}}
